/** Extracts the embedded MP4 segment from Android Motion Photo JPEG files. */
export async function extractMotionPhotoVideo(file) {
    if (!/\.(jpe?g)$/i.test(file.name || '')) return null

    const header = new Uint8Array(await file.slice(0, Math.min(file.size, 2 * 1024 * 1024)).arrayBuffer())
    const xmp = new TextDecoder('utf-8').decode(header)
    const videoItem = [...xmp.matchAll(/<Container:Item\b[^>]*>/gi)]
        .map(([tag]) => {
            const mime = tag.match(/Item:Mime=["']([^"']+)["']/i)?.[1]
            const semantic = tag.match(/Item:Semantic=["']([^"']+)["']/i)?.[1]
            const length = Number(tag.match(/Item:Length=["'](\d+)["']/i)?.[1])
            const padding = Number(tag.match(/Item:Padding=["'](\d+)["']/i)?.[1] || 0)
            return mime === 'video/mp4' && (!semantic || semantic === 'MotionPhoto') && length > 0
                ? { length, padding }
                : null
        })
        .find(Boolean)
    const offsets = [...xmp.matchAll(/(?:MicroVideoOffset|MotionPhotoVideoOffset)["'\s=]+(?:rdf:)?(?:resource=)?["']?(\d+)/gi)]
        .map(match => Number(match[1]))
        .filter(offset => Number.isSafeInteger(offset) && offset > 0 && offset < file.size)
    const candidates = videoItem
        ? [file.size - videoItem.length - videoItem.padding, file.size - videoItem.length]
        : offsets.map(offset => file.size - offset)
    let start = -1
    for (const candidate of candidates) {
        if (candidate < 0 || candidate + 12 > file.size) continue
        const signature = new Uint8Array(await file.slice(candidate, candidate + 12).arrayBuffer())
        if (String.fromCharCode(...signature.subarray(4, 8)) === 'ftyp') {
            start = candidate
            break
        }
    }
    if (start < 0) return null

    const name = file.name.replace(/\.(jpe?g)$/i, '.motion.mp4')
    return new File([file.slice(start)], name, { type: 'video/mp4', lastModified: file.lastModified })
}
