/**
 * 视频压缩参数与校验（与后端 functions/upload/videoCompression.js 保持一致的规则）
 *
 * 视频压缩在服务端完成（Docker 内置 ffmpeg / Workers 外部转码服务），
 * 这里只负责：本地格式与大小预检、把「压缩率」换算成服务端画质参数、拼接 URL 参数。
 */
const MB = 1024 * 1024;

export const SUPPORTED_VIDEO_EXTENSIONS = ['mp4', 'm4v', 'mov', 'webm', 'mkv', 'avi'];
const SUPPORTED_VIDEO_MIMES = ['video/mp4', 'video/quicktime', 'video/webm', 'video/x-matroska', 'video/x-msvideo'];
const KNOWN_VIDEO_EXTENSIONS = [
    ...SUPPORTED_VIDEO_EXTENSIONS,
    'flv', 'f4v', 'wmv', 'ts', 'm2ts', 'mts', '3gp', 'mpg', 'mpeg', 'ogv', 'vob', 'rmvb', 'rm', 'asf', 'divx'
];

export const VIDEO_COMPRESS_DEFAULTS = Object.freeze({
    enabled: false,
    rate: 60,            // 压缩率 0-100，越大体积越小
    targetSize: 20,      // 目标文件大小 MB，0 表示只按压缩率压缩
    threshold: 20,       // 超过该大小(MB)才压缩
    maxInput: 100,       // 输入上限 MB（Workers 请求体上限）
});

function getExtension(name) {
    const match = /\.([^.\/\\]+)$/.exec(String(name || '').trim());
    return match ? match[1].toLowerCase() : '';
}

/** 与后端保持一致：图片/文档返回 false，视频或已知视频扩展名返回 true */
export function isVideoCompressionCandidate(file) {
    const name = file?.name || '';
    const type = String(file?.type || '').split(';')[0].trim().toLowerCase();
    return KNOWN_VIDEO_EXTENSIONS.includes(getExtension(name)) || type.startsWith('video/');
}

export function isSupportedVideoFormat(file) {
    const ext = getExtension(file?.name || '');
    const type = String(file?.type || '').split(';')[0].trim().toLowerCase();
    // 与后端一致：扩展名已知时以扩展名为准，避免 .flv 带上 video/* 被误判为可转码
    if (KNOWN_VIDEO_EXTENSIONS.includes(ext)) return SUPPORTED_VIDEO_EXTENSIONS.includes(ext);
    return SUPPORTED_VIDEO_MIMES.includes(type);
}

export function clampVideoCompressConfig(raw = {}) {
    const clamp = (value, fallback, min, max) => {
        const parsed = Number(value);
        return Number.isFinite(parsed) ? Math.min(max, Math.max(min, parsed)) : fallback;
    };
    const threshold = clamp(raw.threshold, VIDEO_COMPRESS_DEFAULTS.threshold, 1, 200);
    return {
        enabled: raw.enabled === true || raw.enabled === 'true',
        rate: clamp(raw.rate, VIDEO_COMPRESS_DEFAULTS.rate, 0, 100),
        targetSize: clamp(raw.targetSize, VIDEO_COMPRESS_DEFAULTS.targetSize, 0, 1024),
        threshold,
        maxInput: clamp(raw.maxInput, VIDEO_COMPRESS_DEFAULTS.maxInput, 1, 4096),
    };
}

/**
 * 本地预检。返回 { action, message }：
 * - skip: 不需要压缩（未开启 / 非视频 / 未超过阈值）
 * - compress: 允许请求服务端压缩
 * - unsupported / too-large: 给出明确提示并回退到原文件直传/分块上传
 */
export function inspectVideoCompression(file, config) {
    const settings = clampVideoCompressConfig(config);
    if (!settings.enabled || !isVideoCompressionCandidate(file)) return { action: 'skip', settings };
    if (!isSupportedVideoFormat(file)) return { action: 'unsupported', settings };
    if ((file?.size || 0) > settings.maxInput * MB) return { action: 'too-large', settings };
    if ((file?.size || 0) <= settings.threshold * MB) return { action: 'skip', settings };
    return { action: 'compress', settings };
}

/** 拼接单次上传的压缩参数；压缩率越高 -> videoQuality 越低 -> 后端 CRF 越高 */
export function buildVideoCompressionParams(config) {
    const settings = clampVideoCompressConfig(config);
    const quality = Math.round(100 - settings.rate);
    return '&videoCompress=true' +
        `&videoQuality=${quality}` +
        `&videoTargetSizeMB=${settings.targetSize}` +
        `&videoMaxInputMB=${settings.maxInput}`;
}
