/**
 * 动态照片（Live Photo）模式的独立压缩配置。
 *
 * 与普通上传模式的图片压缩 / 服务端视频压缩完全隔离：
 * - 封面图片压缩：沿用 image-conversion 的本地压缩参数；默认关闭，保持「封面原样上传」。
 * - 内嵌视频压缩：浏览器 MediaRecorder 重新编码；默认开启，保持原有「动态视频自动压缩」行为。
 *
 * 这里只做参数归一化与码率换算，不依赖 DOM，便于单元测试。
 */
const MB = 1024 * 1024;

const MIN_VIDEO_BITRATE = 300_000;
const MAX_VIDEO_BITRATE = 2_500_000;
const AUDIO_BITRATE = 96_000;
const MIN_TARGET_BITRATE = 200_000;

export const LIVE_PHOTO_DEFAULTS = Object.freeze({
    coverCompress: false,       // 封面默认原样上传
    coverCompressBar: 5,        // 封面压缩阈值 MB
    coverCompressQuality: 4,    // 封面压缩后期望大小 MB
    coverConvertToWebp: false,  // 封面转 WebP
    videoCompress: true,        // 内嵌视频默认自动压缩
    videoRate: 60,              // 压缩率 0-100
    videoTargetSize: 0,         // 期望大小 MB，0 表示只按压缩率
    videoMaxEdge: 1280,         // 输出视频最大边长 px
});

function clamp(value, fallback, min, max) {
    const parsed = Number(value);
    return Number.isFinite(parsed) ? Math.min(max, Math.max(min, parsed)) : fallback;
}

function isEnabled(value) {
    return value === true || value === 'true';
}

/** 封面图片压缩参数归一化 */
export function clampLivePhotoCoverConfig(raw = {}) {
    const threshold = clamp(raw.threshold, LIVE_PHOTO_DEFAULTS.coverCompressBar, 1, 200);
    return {
        enabled: isEnabled(raw.enabled),
        threshold,
        targetSize: Math.min(clamp(raw.targetSize, LIVE_PHOTO_DEFAULTS.coverCompressQuality, 0.5, 1024), threshold),
        convertToWebp: isEnabled(raw.convertToWebp),
    };
}

/** 内嵌视频压缩参数归一化 */
export function clampLivePhotoVideoConfig(raw = {}) {
    return {
        enabled: isEnabled(raw.enabled),
        rate: clamp(raw.rate, LIVE_PHOTO_DEFAULTS.videoRate, 0, 100),
        targetSize: clamp(raw.targetSize, LIVE_PHOTO_DEFAULTS.videoTargetSize, 0, 1024),
        maxEdge: clamp(raw.maxEdge, LIVE_PHOTO_DEFAULTS.videoMaxEdge, 360, 4096),
    };
}

/**
 * 按压缩率换算视频码率；设置期望大小时再按目标体积与时长加上限约束。
 * 压缩率越高 -> 码率越低 -> 体积越小。
 */
export function resolveLivePhotoVideoBitrate(settings, durationSeconds) {
    const { rate, targetSize } = clampLivePhotoVideoConfig(settings);
    const rateBitrate = Math.round(MIN_VIDEO_BITRATE + (MAX_VIDEO_BITRATE - MIN_VIDEO_BITRATE) * (1 - rate / 100));
    if (targetSize <= 0 || !Number.isFinite(durationSeconds) || durationSeconds <= 0) {
        return rateBitrate;
    }

    const targetBitrate = Math.floor((targetSize * 8 * MB) / durationSeconds) - AUDIO_BITRATE;
    if (targetBitrate <= 0) return rateBitrate;
    return Math.min(rateBitrate, Math.max(MIN_TARGET_BITRATE, targetBitrate));
}
